CREATE TABLE "AiPostIncidentReview" ("id" TEXT NOT NULL,"incidentId" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"rootCause" TEXT NOT NULL,"contributingFactors" TEXT,"correctiveActions" TEXT NOT NULL,"preventiveActions" TEXT,"guardrailLearning" TEXT,"recoveryMinutes" INTEGER,"recurrenceRisk" TEXT NOT NULL DEFAULT 'MEDIUM',"validated" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiPostIncidentReview_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "AiPostIncidentReview_incidentId_key" ON "AiPostIncidentReview"("incidentId");CREATE INDEX "AiPostIncidentReview_agencyId_createdAt_idx" ON "AiPostIncidentReview"("agencyId","createdAt");